class Temperature:
    def __init__(self, celsius):
        if celsius < -273.15:
            raise ValueError('below absolute zero')
        self.celsius = celsius

    def fahrenheit(self):
        return self.celsius * 9 / 5 + 32

boiling = Temperature(100)
freezing = Temperature(0)
assert boiling.fahrenheit() == 212.0
assert freezing.fahrenheit() == 32.0
try:
    Temperature(-300)
    raise AssertionError('expected ValueError')
except ValueError:
    pass
print(boiling.fahrenheit(), freezing.fahrenheit())
